package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;
/** Re-times/re-shapes a serial payload only when input link quality clears a configurable decision threshold. */
public class DigitalRegeneratorBlock extends DirectionalDomainBlock{public static final IntegerProperty THRESHOLD=IntegerProperty.create("threshold",0,2);private static final int[]MIN_Q={20,40,60};public DigitalRegeneratorBlock(Properties p){super(p);registerDefaultState(defaultBlockState().setValue(THRESHOLD,1));}@Override public MapCodec<DigitalRegeneratorBlock> codec(){return RedstoneEngineering.DIGITAL_REGENERATOR_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){super.createBlockStateDefinition(b);b.add(THRESHOLD);}private void update(ServerLevel l,BlockPos p,BlockState s){BlockPos in=inputPos(p,s),out=outputPos(p,s);int iq=InformationRuntime.quality(l,"serial",in);boolean ok=InformationRuntime.valid(l,"serial",in)&&iq>=MIN_Q[s.getValue(THRESHOLD)];int v=InformationRuntime.value(l,"serial",in),period=Math.max(1,InformationRuntime.aux(l,"serial",in));InformationRuntime.write(l,"serial",p,v,period,ok,ok?100:0);if(l.getBlockState(out).getBlock() instanceof SerialDataLineBlock)SerialNetwork.drive(l,out,v,period,ok,ok?100:0);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)sl.scheduleTick(p,this,2);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){update(l,p,s);l.scheduleTick(p,this,2);}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block nb,BlockPos np,boolean m){if(l instanceof ServerLevel sl)update(sl,p,s);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){int n=(s.getValue(THRESHOLD)+1)%3;BlockState ns=s.setValue(THRESHOLD,n);l.setBlock(p,ns,Block.UPDATE_CLIENTS);int iq=InformationRuntime.quality(l,"serial",inputPos(p,ns));pl.displayClientMessage(Component.literal("Digital regenerator minQuality="+MIN_Q[n]+"% inputQuality="+iq+"% output="+(InformationRuntime.valid(l,"serial",p)?"VALID":"REJECTED")),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}
